CREATE COLUMN TABLE "TEST_AP"."OSTT" ("AbsId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(40) NOT NULL , "UserSign" SMALLINT CS_INT, "IsVat" NVARCHAR(1) DEFAULT 'N', "NfTaxId" INTEGER CS_INT, "TpsId" INTEGER CS_INT, "PLABalance" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreditCtrl" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OSTT_NAME" ON "TEST_AP"."OSTT" ( "Name" ASC )